public abstract class METCustomerMDFPosting_FreeTextInvoice extends METCustomerMDFPosting
{
    CustInvoiceTable custInvoiceTable;

}

Method.Source:
CustInvoiceTable createCustInvoiceTableHeader(METCustomerMDFConsolidationTable _consolidationPosting)
{
    CustInvoiceTable custInvoiceTableInsert;
    CustTable custTable;

    custInvoiceTableInsert.initValue();

    custTable = CustTable::find(_consolidationPosting.CustAccount);
    custInvoiceTableInsert.initFromCustTable(custTable);

    if(custInvoiceTableInsert.validateWrite())
    {
        custInvoiceTableInsert.insert();
    }

    return custInvoiceTableInsert;
}

RecId createCustInvoiceLine(METCustomerMDFConsolidationTable _consolidationPosting)
{
    CustInvoiceLine custInvoiceLine;
    MetCustomerMdfSetupTable customerMDFSetupTable;

    customerMDFSetupTable = MetCustomerMdfSetupTable::findRecId(_consolidationPosting.CustomerMDFSetupTable);

    custInvoiceLine.clear();
    custInvoiceLine.initValue();
    custInvoiceLine.LineNum = CustInvoiceLine::lastLineNum_W(custInvoiceLine.ParentRecId);
    custInvoiceLine.ParentRecId = custInvoiceTable.RecId;
    custInvoiceLine.initFromCustInvoiceTable(custInvoiceTable);
    custInvoiceLine.Description = customerMDFSetupTable.Description;
    custInvoiceLine.TaxItemGroup = customerMDFSetupTable.GST;
    custInvoiceLine.UnitPrice = _consolidationPosting.MDF;
    custInvoiceLine.LedgerDimension = 5637173827;

    if(custInvoiceLine.validateWrite())
    {
        custInvoiceLine.insert();
    }

    return custInvoiceLine.RecId;
}
